import math
from mpmath import betainc, findroot
def tcdf(t, df):
    x = df / (df + t * t)
    p = 0.5 * betainc(df / 2.0, 0.5, 0, x, regularized=True)
    return float(1 - p if t > 0 else p)
def tinv(p, df):
    return float(findroot(lambda t: tcdf(t, df) - p, 2.0))
def ncdf(z):
    return 0.5 * (1 + math.erf(z / math.sqrt(2)))
def zstar(p):
    return float(findroot(lambda z: ncdf(z) - p, 1.5))
def welch(s1, n1, s2, n2):
    a = s1 * s1 / n1; b = s2 * s2 / n2
    return math.sqrt(a + b), (a + b) ** 2 / (a * a / (n1 - 1) + b * b / (n2 - 1))
xs = [30, 40, 50, 60, 70, 80, 90, 100, 110, 120, 130, 140]
ys = [11.1, 9.0, 7.4, 6.4, 5.9, 5.9, 6.4, 7.4, 9.0, 11.1, 13.7, 16.8]
pk = 4
f = lambda x: 5.8 + 0.0026 * (x - 75) ** 2
assert max(abs(y - f(x)) for x, y in zip(xs, ys)) <= 0.51
assert all(ys[i] >= ys[i + 1] for i in range(pk))
assert all(ys[i] <= ys[i + 1] for i in range(pk, len(ys) - 1))
assert ys[0] > ys[4] and xs[0] < xs[4]
assert min(y for x, y in zip(xs, ys) if x > 100) > max(y for x, y in zip(xs, ys) if 50 <= x <= 80)
print("ALL_CHECKS_PASSED")

